def grouped_whiten(
    values: torch.Tensor,
    group_ids: torch.Tensor,
    eps: float = 1e-6,
    scale_by_std: bool = True,
) -> torch.Tensor:
    if values.numel() == 0:
        return values
    order = torch.argsort(group_ids, stable=True)
    sorted_vals = values.index_select(0, order)
    sorted_groups = group_ids.index_select(0, order)
    _, counts = torch.unique_consecutive(sorted_groups, return_counts=True)

    whitened_groups = []
    for grp in torch.split(sorted_vals, counts.tolist()):
        if grp.numel() <= 1:
            whitened_groups.append(torch.zeros_like(grp))
        else:
            mean = torch.mean(grp)
            std = torch.std(grp)
            whitened_groups.append((grp - mean) / (std + eps) if scale_by_std else (grp - mean))

    whitened = torch.cat(whitened_groups, dim=0)
    return torch.gather(whitened, 0, order)


